div.script:

function escapeForSrcdoc(str) {
  // 
  return str
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;');
}

async function loadContent() {
  try {
    const response = await fetch('https://raw.githubusercontent.com/zaka13alt/sitesinglefile/refs/heads/main/idk.html');
    if (!response.ok) throw new Error('Network error');
    const rawHtml = await response.text();

    // 
    document.getElementById('viewer').setAttribute('srcdoc', escapeForSrcdoc(rawHtml));
  } catch (err) {
    document.getElementById('viewer').setAttribute('srcdoc', '<p style="color:red;">Error loading document.</p>');
  }
}

loadContent();
